     1                                      const struct bpf_core_spec *spec,
     2                                      __u32 *val, __u32 *field_sz, __u32 *type_id,
     3                                      bool *validate)
     4  {
     5          const struct bpf_core_accessor *acc;
     6          const struct btf_type *t;
     7          __u32 byte_off, byte_sz, bit_off, bit_sz, field_type_id;
     8          const struct btf_member *m;
     9          const struct btf_type *mt;
    10          bool bitfield;
    11          __s64 sz;
    12
    13          *field_sz = 0;
    14
    15          if (relo->kind == BPF_FIELD_EXISTS) {
    16                  *val = spec ? 1 : 0;
    17                  return 0;
    18          }
    19
    20          if (!spec)
    21                  return -EUCLEAN; /* request instruction poisoning */
    22
    23          acc = &spec->spec[spec->len - 1];
    24          t = btf__type_by_id(spec->btf, acc->type_id);
    25
    26          /* a[n] accessor needs special handling */
    27          if (!acc->name) {
    28                  if (relo->kind == BPF_FIELD_BYTE_OFFSET) {
    29                          *val = spec->bit_offset / 8;
    30                          /* remember field size for load/store mem size */
    31                          sz = btf__resolve_size(spec->btf, acc->type_id);
    32                          if (sz < 0)
    33                                  return -EINVAL;
    34                          *field_sz = sz;
    35                          *type_id = acc->type_id;
    36                  } else if (relo->kind == BPF_FIELD_BYTE_SIZE) {
    37                          sz = btf__resolve_size(spec->btf, acc->type_id);
    38                          if (sz < 0)
    39                                  return -EINVAL;
    40                          *val = sz;
    41                  } else {
    42                          pr_warn("prog '%s': relo %d at insn #%d can't be applied to array access\n",
    43                                  prog_name, relo->kind, relo->insn_off / 8);
    44                          return -EINVAL;
    45                  }
    46                  if (validate)
    47                          *validate = true;
    48                  return 0;
    49          }
    50
    51          m = btf_members(t) + acc->idx;
    52          mt = skip_mods_and_typedefs(spec->btf, m->type, &field_type_id);
    53          bit_off = spec->bit_offset;
    54          bit_sz = btf_member_bitfield_size(t, acc->idx);
    55
    56          bitfield = bit_sz > 0;
    57          if (bitfield) {
    58                  byte_sz = mt->size;
    59                  byte_off = bit_off / 8 / byte_sz * byte_sz;
    60                  /* figure out smallest int size necessary for bitfield load */
    61                  while (bit_off + bit_sz - byte_off * 8 > byte_sz * 8) {
    62                          if (byte_sz >= 8) {
    63                                  /* bitfield can't be read with 64-bit read */
    64                                  pr_warn("prog '%s': relo %d at insn #%d can't be satisfied for bitfield\n",
    65                                          prog_name, relo->kind, relo->insn_off / 8);
    66                                  return -E2BIG;
    67                          }
    68                          byte_sz *= 2;
    69                          byte_off = bit_off / 8 / byte_sz * byte_sz;
    70                  }
    71          } else {
    72                  sz = btf__resolve_size(spec->btf, field_type_id);
    73                  if (sz < 0)
    74                          return -EINVAL;
    75                  byte_sz = sz;
    76                  byte_off = spec->bit_offset / 8;
    77                  bit_sz = byte_sz * 8;
    78          }
    79
    80          /* for bitfields, all the relocatable aspects are ambiguous and we
    81           * might disagree with compiler, so turn off validation of expected
    82           * value, except for signedness
    83           */
    84          if (validate)
    85                  *validate = !bitfield;
    86
    87          switch (relo->kind) {
    88          case BPF_FIELD_BYTE_OFFSET:
    89                  *val = byte_off;
    90                  if (!bitfield) {
    91                          *field_sz = byte_sz;
    92                          *type_id = field_type_id;
    93                  }
    94                  break;
    95          case BPF_FIELD_BYTE_SIZE:
    96                  *val = byte_sz;
    97                  break;
    98          case BPF_FIELD_SIGNED:
    99                  /* enums will be assumed unsigned */
   100                  *val = btf_is_enum(mt) ||
   101                         (btf_int_encoding(mt) & BTF_INT_SIGNED);
   102                  if (validate)
   103                          *validate = true; /* signedness is never ambiguous */
   104                  break;
   105          case BPF_FIELD_LSHIFT_U64:
   106  #if __BYTE_ORDER == __LITTLE_ENDIAN
   107                  *val = 64 - (bit_off + bit_sz - byte_off  * 8);
   108  #else
   109                  *val = (8 - byte_sz) * 8 + (bit_off - byte_off * 8);
   110  #endif
   111                  break;
   112          case BPF_FIELD_RSHIFT_U64:
   113                  *val = 64 - bit_sz;
   114                  if (validate)
   115                          *validate = true; /* right shift is never ambiguous */
   116                  break;
   117          case BPF_FIELD_EXISTS:
   118          default:
   119                  return -EOPNOTSUPP;
   120          }
   121
   122          return 0;
   123  }
